func testResourceToManyRemoveOpChildIdResources(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Resource
	var b, c, d, e Resource

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, resourceDBTypes, false, strmangle.SetComplement(resourcePrimaryKeyColumns, resourceColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Resource{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, resourceDBTypes, false, strmangle.SetComplement(resourcePrimaryKeyColumns, resourceColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddChildIdResources(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.ChildIdResources().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveChildIdResources(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.ChildIdResources().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if len(b.R.ParentIdResources) != 0 {
		t.Error("relationship was not removed properly from the slice")
	}
	if len(c.R.ParentIdResources) != 0 {
		t.Error("relationship was not removed properly from the slice")
	}
	if d.R.ParentIdResources[0] != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}
	if e.R.ParentIdResources[0] != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}

	if len(a.R.ChildIdResources) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.ChildIdResources[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.ChildIdResources[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

func testResourceToOneTenantUsingTenantIdTenant(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local Resource
	var foreign Tenant

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, resourceDBTypes, false, resourceColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Resource struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, tenantDBTypes, false, tenantColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Tenant struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	local.TenantId = foreign.ID
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.TenantIdTenant().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if check.ID != foreign.ID {
		t.Errorf("want: %v, got %v", foreign.ID, check.ID)
	}

	ranAfterSelectHook := false
	AddTenantHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *Tenant) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := ResourceSlice{&local}
	if err = local.L.LoadTenantIdTenant(ctx, tx, false, (*[]*Resource)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.TenantIdTenant == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.TenantIdTenant = nil
	if err = local.L.LoadTenantIdTenant(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.TenantIdTenant == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

func testResourceToOneSetOpTenantUsingTenantIdTenant(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Resource
	var b, c Tenant

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, resourceDBTypes, false, strmangle.SetComplement(resourcePrimaryKeyColumns, resourceColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, tenantDBTypes, false, strmangle.SetComplement(tenantPrimaryKeyColumns, tenantColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, tenantDBTypes, false, strmangle.SetComplement(tenantPrimaryKeyColumns, tenantColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*Tenant{&b, &c} {
		err = a.SetTenantIdTenant(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.TenantIdTenant != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.TenantIdResources[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if a.TenantId != x.ID {
			t.Error("foreign key was wrong value", a.TenantId)
		}

		zero := reflect.Zero(reflect.TypeOf(a.TenantId))
		reflect.Indirect(reflect.ValueOf(&a.TenantId)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if a.TenantId != x.ID {
			t.Error("foreign key was wrong value", a.TenantId, x.ID)
		}
	}
}

